using System.ComponentModel;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Build the IChatClient via MEAI abstraction ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Define tools ---
var tools = new ResearchTools();
var aiTools = new AITool[]
{
    AIFunctionFactory.Create(tools.SearchWeb),
    AIFunctionFactory.Create(tools.SaveNote),
    AIFunctionFactory.Create(tools.GetNotes),
};

// --- Create the agent ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic:
        1. Use the SearchWeb tool multiple times with different queries to gather information.
        2. Use the SaveNote tool to record key findings as you go.
        3. After gathering enough information, use GetNotes to review everything you saved.
        4. Provide a well-structured summary with the key points you discovered.
        Be thorough — search at least 2-3 different angles of the topic.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: aiTools);

// --- Run the agent ---
Console.WriteLine("Research Agent");
Console.WriteLine(new string('=', 50));
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var session = await agent.CreateSessionAsync();
var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

await foreach (var update in agent.RunStreamingAsync(messages, session, runOptions))
{
    Console.Write(update.Text);
}

Console.WriteLine();
Console.WriteLine(new string('=', 50));
Console.WriteLine($"\nNotes collected ({tools.NoteCount}):");
foreach (var note in tools.AllNotes)
{
    Console.WriteLine($"  • {note}");
}

// --- Tool implementations ---
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private static readonly JsonSerializerOptions s_jsonOptions = new() { WriteIndented = true };

    public int NoteCount => _notes.Count;
    public IReadOnlyList<string> AllNotes => _notes;

    [Description("Search the web for information on a query. Returns a list of search result snippets.")]
    public static string SearchWeb(
        [Description("The search query string")] string query)
    {
        // Simulated web search results for demonstration purposes.
        // In production, replace with a real search API (Bing, Google, etc.).
        var results = GenerateSimulatedResults(query);
        return JsonSerializer.Serialize(new { query, results }, s_jsonOptions);
    }

    [Description("Save a note with key findings from your research.")]
    public string SaveNote(
        [Description("The note text to save")] string note)
    {
        _notes.Add(note);
        return $"Note saved (total notes: {_notes.Count}).";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        return JsonSerializer.Serialize(
            _notes.Select((n, i) => new { index = i + 1, note = n }),
            s_jsonOptions);
    }

    private static List<SearchResult> GenerateSimulatedResults(string query)
    {
        var lowerQuery = query.ToLowerInvariant();
        var results = new List<SearchResult>();

        // Return contextual simulated results based on common query patterns
        if (lowerQuery.Contains("history") || lowerQuery.Contains("origin"))
        {
            results.Add(new("Historical Overview", $"The history of {query} dates back several decades, with key milestones in research and development shaping its evolution.", "https://example.com/history"));
            results.Add(new("Timeline of Key Events", $"Major events related to {query} include foundational discoveries, landmark publications, and pivotal technological breakthroughs.", "https://example.com/timeline"));
        }
        else if (lowerQuery.Contains("benefit") || lowerQuery.Contains("advantage") || lowerQuery.Contains("impact"))
        {
            results.Add(new("Key Benefits", $"The primary benefits of {query} include improved efficiency, cost reduction, and enhanced capabilities in related fields.", "https://example.com/benefits"));
            results.Add(new("Impact Analysis", $"Studies show that {query} has had significant positive impact on productivity and innovation across multiple industries.", "https://example.com/impact"));
        }
        else if (lowerQuery.Contains("challenge") || lowerQuery.Contains("risk") || lowerQuery.Contains("concern"))
        {
            results.Add(new("Challenges and Risks", $"Key challenges associated with {query} include scalability concerns, ethical considerations, and implementation complexity.", "https://example.com/challenges"));
            results.Add(new("Expert Concerns", $"Experts have raised concerns about {query} related to long-term sustainability and potential unintended consequences.", "https://example.com/concerns"));
        }
        else if (lowerQuery.Contains("future") || lowerQuery.Contains("trend") || lowerQuery.Contains("outlook"))
        {
            results.Add(new("Future Outlook", $"The future of {query} looks promising with emerging trends pointing toward broader adoption and continued innovation.", "https://example.com/future"));
            results.Add(new("Emerging Trends", $"Current trends in {query} include increased automation, integration with AI systems, and growing investment.", "https://example.com/trends"));
        }
        else
        {
            results.Add(new("Overview", $"{query} is a significant topic in its field, encompassing various aspects from theory to practical applications.", "https://example.com/overview"));
            results.Add(new("Recent Developments", $"Recent developments in {query} highlight advances in technology and methodology that are driving the field forward.", "https://example.com/recent"));
            results.Add(new("Expert Analysis", $"Leading experts describe {query} as a transformative area with wide-ranging implications for industry and society.", "https://example.com/analysis"));
        }

        return results;
    }

    private record SearchResult(string Title, string Snippet, string Url);
}

